import axios from "axios";

// ✅ FIX 13: BASE URL comes from the environment variable — NOT hardcoded to localhost.
//            When another device on the LAN opens the React app, "localhost" in the
//            browser resolves to *that device*, not your dev machine.
//            Set REACT_APP_API_URL=http://<your-LAN-IP>:8080 in your .env file.
const BASE = process.env.REACT_APP_API_URL || "http://localhost:8080";

const api = axios.create({ baseURL: BASE });

// Attach JWT token to every request automatically
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("crisp_token");
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

// ── Auth ─────────────────────────────────────────────────────────────────────
export const login = (username, password) =>
  api.post("/api/auth/login", { username, password });

export const register = (username, password, fullName) =>
  api.post("/api/auth/register", { username, password, fullName });

// ── Rooms ─────────────────────────────────────────────────────────────────────
export const getUserRooms = (username) =>
  api.get(`/api/rooms/user/${username}`);

export const createRoom = (body) =>
  api.post("/api/rooms/create", body);

export const getChatHistory = (roomId) =>
  api.get(`/api/rooms/${roomId}/history`);

// ── Users ─────────────────────────────────────────────────────────────────────
export const getAllUsers  = ()  => api.get("/api/users");
export const getOnlineUsers = () => api.get("/api/users/online");

export default api;
